, "id": "e1931bf1-56d8-5868-b373-bbb8e29e25fc"}, {"title": "新五代史·卷九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/76880fa37d0bdb722c1238d971903f0fd476eb32/content/books/zizhi-tongjian/vol-283/year-0944/part-01/sources/library/xinwudaishi-009-944-january/source.txt", "note": "《新五代史》卷九，段落 xin-wudaishi-b08f244b9241-p000335；EPUB电子本，纸本及异文待核", "id": "71c7fc99-919d-58e5-acc1-c401819fcdc4"}, {"title": "资治通鉴·唐纪八十一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0ad8e2bd/content/books/zizhi-tongjian/vol-265/year-0905/part-06/sources/library/tongjian-265-905-autumn/source.txt", "note": "《资治通鉴》唐纪八十一，段落 zizhi-tongjian-a63549944a71-p003147；电子底本待考，分段待核", "id": "b2850f0b-b82e-523c-96f0-12ebaf2b3605"}]'::jsonb)
