INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "刘金", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：刘金。", "biography": null, "status": "draft", "id": "f52d5f3e-f0ed-5141-b2d1-7c46f0142156"}, {"name": "刘仁规", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷265天祐二年条所见人物：刘仁规。", "biography": null, "status": "draft", "id": "707144e1-d0eb-5e30-999b-feaca280e2bd"}, {"name": "刘崇俊", "aliases": ["劉崇俊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘崇俊，话中比较的濠州人物。", "biography": null, "status": "draft", "id": "e6be30bd-ff7c-551d-be1e-822ade03a7b7"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "姚景", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐清淮节度使。944年条下追述其去世后，刘崇俊求兼寿州。具体生卒年月未载，不将死亡定为944年。", "biography": null, "status": "draft", "id": "1a207dc3-0eef-59dc-8f01-f5b4051018ca"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "刘彦贞", "aliases": ["劉彥貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘信之子，南唐楚州刺史。944年条下追述他改任濠州观察使，迅速前往替代刘崇俊。具体任职年月与生卒年未载。", "biography": null, "status": "draft", "id": "3a86e5c0-cc8e-5120-888d-a75e599e8e30"}, {"name": "刘信", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：刘信。", "biography": null, "status": "draft", "id": "e00e40ed-f971-5df9-b8a9-4dc1cc38f275"}, {"name": "康彦进", "aliases": ["康彥進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋深州刺史。944年九月丙子击退侵入遂城、乐寿的契丹军。生卒年本段未载。", "biography": null, "status": "draft", "id": "ed4e9efe-e4f0-54f5-bb1e-a807cf8abfac"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘泽", "aliases": ["劉弘泽", "刘洪澤", "劉洪澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘泽，获封王爵之子。", "biography": null, "status": "draft", "id": "8dd9ffe2-f19c-50ef-8a89-32027a5144f7"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "陈敬佺", "aliases": ["陳敬佺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "殷国将领。944年王延政派他率三千兵驻尤溪、古田。生卒年本段未载。", "biography": null, "status": "draft", "id": "916be362-3a03-5618-8f43-0085be512948"}, {"name": "卢进", "aliases": ["盧進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "殷国将领。944年王延政派他率两千兵驻长溪。没有证据将其与下一段的杜进直接合并。生卒年本段未载。", "biography": null, "status": "draft", "id": "e2e925e5-3070-5f52-9c34-ffe28dad6e88"}, {"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "王忠顺", "aliases": ["王忠順"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年与留从效、董思安、张汉思议反朱文进政权，参与泉州政变后被王延政任为都指挥使。生卒年本段未载。", "biography": null, "status": "draft", "id": "5c73751d-6af3-5516-935f-53a4ace23f02"}, {"name": "董思安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年参与反朱文进的谋议和泉州政变，后被王延政任为都指挥使。生卒年本段未载。", "biography": null, "status": "draft", "id": "385e66d6-1650-5db4-a215-4208ca968420"}, {"name": "张汉思", "aliases": ["張漢思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年与留从效等谋议反对朱文进。《宋史》对应谋议另记苏光诲，各书名单分别保留，不以名单不同将两人合并。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4bde2a9d-80c0-5d9e-abb2-5f2f4dfbf727"}, {"name": "苏光诲", "aliases": ["蘇光誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《宋史》留从效传所记留从效亲近之人，参与944年泉州恢复王氏的谋议。该书名单与通鉴不同，不等同张汉思。生卒年本段未载。", "biography": null, "status": "draft", "id": "a4be1dd2-0c10-5d7d-aa06-602ee882924d"}, {"name": "黄绍颇", "aliases": ["黃紹頗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，连江人。陈匡范借款补额一事暴露后，王延羲任黄绍颇为国计使。黄绍颇建议对不属荫补的求官者按条件收钱授官，王延羲接受。具体年月和生卒年未载。", "biography": null, "status": "draft", "id": "534bfbe9-b7bc-5b90-8054-1bb004f6b7c7"}, {"name": "王继勋", "aliases": ["王繼勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的从子，王氏宗族成员。944年留从效杀黄绍颇后请他主持泉州军府，王延政随后任他为侍中、泉州刺史。具体亲生父姓名本段未载。", "biography": null, "status": "draft", "id": "3ecb3355-a3dd-5a2f-a0b9-12d6af9a06ab"}, {"name": "陈洪进", "aliases": ["陳洪進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州副兵马使，主书称临淮，《宋史》记泉州仙游人，地名表述对应关系待核。944年将黄绍颇首级送建州，以说辞突破尤溪阻兵，获王延政任官。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "2fa634eb-359d-513d-8ba2-8168587d3cb7"}, {"name": "程谟", "aliases": ["程謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "漳州将领。944年闻泉州政变后杀刺史程文纬，立王继成暂掌漳州。与程文纬及新史作程贇的漳州守将分开。生卒年本段未载。", "biography": null, "status": "draft", "id": "9500b575-fc4b-580e-8ffa-fc054824a2c9"}, {"name": "程文纬", "aliases": ["程文緯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国左军使，944年朱文进掌权后任漳州刺史。《新五代史》相同政局的漳州守将写程贇，是否同人异名待核，未直接合并。生卒年未载。", "biography": null, "status": "draft", "id": "a9868a49-25bf-55fb-829a-1e4110d2e03a"}, {"name": "王继成", "aliases": ["王繼成"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的从子，王氏宗族成员。944年程谟杀漳州刺史后立他暂掌漳州。亲生父姓名本段未载。", "biography": null, "status": "draft", "id": "4f09de43-cd4b-56a5-a731-b286597a2338"}, {"name": "许文稹", "aliases": ["許文稹", "许文缜", "許文縝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "同安人，汀州刺史。944年朱文进掌权后率郡投降朱文进。《新五代史》对应汀州守将作許文縝，保留姓名字形异文；该书后文投降王延政为另一阶段，不混为当前投降对象。生卒年未载。", "biography": null, "status": "draft", "id": "6717f767-1ab2-52b8-8015-c778cc06ee45"}, {"name": "朱文进", "aliases": ["硃文进", "朱文進", "硃文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "永泰人，闽国拱宸军将领。《资治通鉴》记他与连重遇多次受王继鹏侮辱而心怀不满，《新五代史》还记二人因宸卫军待遇优厚而激怒部众。生卒年未载。", "biography": null, "status": "draft", "id": "309ef83c-46fe-51a1-86cc-c2cb8dc48d82"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "杨承贵", "aliases": ["楊承貴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远之子。940年受父亲派遣围范延光私宅，逼其自尽，随后把范延光推入河中。《新五代史》相关执行者写杨承勋，姓名异说未裁定，不自动合并。生卒年未载。", "biography": null, "status": "draft", "id": "daf29c5e-0a0a-5cc1-aa88-e64404212a3c"}, {"name": "杨承祚", "aliases": ["楊承祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。938年五月被任命为左威卫将军，并与石敬瑭的女儿长安公主结婚。", "biography": null, "status": "draft", "id": "2af4e0bd-ddb5-5c72-b4f6-8e3394d31c7d"}, {"name": "杨承信", "aliases": ["楊承信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。《资治通鉴》称他为次子，938年五月与杨承祚同获优厚任官，具体官名未载。", "biography": null, "status": "draft", "id": "70bde002-fc6d-5293-9fb1-214458b656a6"}, {"name": "丘涛", "aliases": ["丘濤", "邱涛", "邱濤"], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "杨光远的节度判官，曾劝其叛乱。944年杨承勋决定开城投降时被杀。旧史作邱濤，对应职务和同一被杀场景，保留姓名异文。出生年未载。", "biography": null, "status": "draft", "id": "27059f17-d954-53b1-a560-bc2bb7dab082"}, {"name": "杜延寿", "aliases": ["杜延壽"], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "杨光远的亲将。944年杨承勋决定投降时与丘涛、杨瞻、白延祚等被杀。姓名来自新旧五代史，不因同音与其他杜延姓将领合并。出生年未载。", "biography": null, "status": "draft", "id": "8836c94f-2973-5fdd-ba9d-a7d21a56bdcf"}, {"name": "杨瞻", "aliases": ["楊瞻"], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "杨光远的亲将。944年杨承勋决定投降时被杀。新旧传记作楊瞻，旧本纪同列人物作楊贍，姓名字形待核，不直接写成已证别名。出生年未载。", "biography": null, "status": "draft", "id": "0550691c-d911-5cde-ae7e-76238b16a847"}, {"name": "白延祚", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "杨光远的亲将。944年杨承勋决定投降时与其他亲将被杀。出生年未载。", "biography": null, "status": "draft", "id": "b9d47cc5-95c5-5844-a265-f8d4c1475878"}, {"name": "王德柔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "即墨县令。944年青州开城归降后，奉杨承勋等之命向后晋递交请罪表。生卒年本段未载。", "biography": null, "status": "draft", "id": "1c9a70b0-0d06-5068-8049-9f12f8fd06c4"}, {"name": "杨麟（杨光远判官）", "aliases": ["楊麟（楊光遠判官）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的节度判官。944年青州归降时奉杨光远命向后晋递交请死表。与903年已录同名人缺少连续身份依据，暂分档保留待核。生卒年本段未载。", "biography": null, "status": "draft", "id": "8312b0a7-e97b-5e5f-a3a5-e225be5f8d11"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

